function plot_switch_latent_random(input,params)
% % plot_switch_lantent_random %
%PURPOSE:   Plot choice behavior around switches, when the high reward
%           side has changed
%AUTHORS:   H Atilgan & AC Kwan 04292020
%
%INPUT ARGUMENTS
%   input:  Structure generated by choice_switch_hrside().
%   tlabel: Text string that will be put on top of the figure

%%
if numel(input)>1  %more than 1 data set, plot mean+-sem
    n=input{1}.n;
    numRange=input{1}.numRange;
    L1_ranges=input{1}.L1_ranges;
    L2_ranges=input{1}.L2_ranges;
    for j=1:numel(input)
        temp_prob(:,:,j)=input{j}.prob;    
    end
    prob=nanmean(temp_prob,3);
    prob_sem=nanstd(temp_prob,[],3)./sqrt(numel(input));
else        %plot the 1 data set
    n=input.n;
    prob=input.prob;
    numRange=input.numRange;
    L1_ranges=input.L1_ranges;
    L2_ranges=input.L2_ranges;
end

figure;
cmap = brewermap(10,'PuOr');
hold on;

%plot probability of choosing initial best option
for k=1:numRange
    legendNum = 1;
    subplot(1,4,k); hold on;
    
    %plot dotted line at trial = 0
    plot([0 0], params.ylim,'k--','LineWidth',2);
    
    %plot the mean
    h(legendNum) = plot(n,prob(:,k),'.-','MarkerSize',30,'Linewidth',3,'Color',cmap(k,:));
    %if more than 1 data set, then plot the error bars
    if numel(input)>1
        for l=1:numel(n)
            plot(n(l)*[1 1],prob(l,k)+prob_sem(l,k)*[-1 1],'-','LineWidth',3,'Color',cmap(k,:));
        end
    end
    
    legstring{legendNum}=[ 'L_{Random}: ' int2str(L2_ranges(k,1)) '-' int2str(L2_ranges(k,2))];

    title(legstring);
    ylabel(params.ylabel{:});
    xlabel('Trial from block switch');
    axis([n(1) n(end) params.ylim]);
end


set(gcf,'Position',[30 30 1500 500]);

end


